package net.hivel.islandsrpg.util;
import org.bukkit.*; import org.bukkit.enchantments.Enchantment; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta; import org.bukkit.persistence.*; import org.bukkit.plugin.java.JavaPlugin; import java.util.*;
public class ItemBuilder { private final ItemStack item; public ItemBuilder(Material m){item=new ItemStack(m==null?Material.STONE:m);} public ItemBuilder name(String n){ItemMeta meta=item.getItemMeta(); meta.setDisplayName(ColorUtil.color(n)); item.setItemMeta(meta); return this;} public ItemBuilder lore(List<String> lore){ItemMeta meta=item.getItemMeta(); meta.setLore(ColorUtil.color(lore)); item.setItemMeta(meta); return this;} public ItemBuilder glow(boolean g){ if(g){ItemMeta meta=item.getItemMeta(); meta.addEnchant(Enchantment.UNBREAKING,1,true); meta.addItemFlags(ItemFlag.HIDE_ENCHANTS);} return this;} public ItemBuilder unbreakable(boolean b){ItemMeta meta=item.getItemMeta(); meta.setUnbreakable(b); meta.addItemFlags(ItemFlag.HIDE_UNBREAKABLE); item.setItemMeta(meta); return this;} public ItemBuilder pdc(JavaPlugin p,String key,String value){ItemMeta meta=item.getItemMeta(); meta.getPersistentDataContainer().set(new NamespacedKey(p,key), PersistentDataType.STRING,value); item.setItemMeta(meta); return this;} public ItemStack build(){return item;} }
